import numpy as np

def make_obs(agent_cells, moving_cells=None, reward_cells=None, obstacle_cells=None, prev_cells=None):
    x = np.zeros((10, 10, 5))
    # wall border
    x[0, :, 3] = 1
    x[9, :, 3] = 1
    x[:, 0, 3] = 1
    x[:, 9, 3] = 1
    for (r, c) in agent_cells:
        x[r, c, 0] = 1
    if moving_cells:
        for (r, c) in moving_cells:
            x[r, c, 1] = 1
    if reward_cells:
        for (r, c) in reward_cells:
            x[r, c, 2] = 1
    if obstacle_cells:
        for (r, c) in obstacle_cells:
            x[r, c, 3] = 1
    if prev_cells:
        for (r, c) in prev_cells:
            x[r, c, 4] = 1
    return x.flatten()

# vertical 3-cell paddle on the left side, rows 4-6, column 1
agent = [(4, 1), (5, 1), (6, 1)]

batch = []
labels = []

# baseline: no ball
batch.append(make_obs(agent))
labels.append('no_ball')

# ball (moving object) at column 8, varying row 1..8
for r in range(1, 9):
    batch.append(make_obs(agent, moving_cells=[(r, 8)]))
    labels.append(f'ball_row_{r}')

X = np.array(batch)
out = forward(X)
actions = np.argmax(out, axis=1)

for label, logits, act in zip(labels, out, actions):
    print(f'{label}: action={act} logits={np.round(logits, 2)}')

import numpy as np

def make_obs(agent=[], obstacles=[], rewards=[], moving=[], prev=[]):
    x = np.zeros((10, 10, 5))
    # wall border channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[r, c, 3] = 1
    for r, c in agent:
        x[r, c, 0] = 1
    for r, c in obstacles:
        x[r, c, 3] = 1
    for r, c in rewards:
        x[r, c, 2] = 1
    for r, c in moving:
        x[r, c, 1] = 1
    for r, c in prev:
        x[r, c, 4] = 1
    return x.flatten()

cases = {
    'baseline':   make_obs(agent=[(4, 4)]),
    'obs_right':  make_obs(agent=[(4, 4)], obstacles=[(4, 5)]),
    'obs_left':   make_obs(agent=[(4, 4)], obstacles=[(4, 3)]),
    'obs_up':     make_obs(agent=[(4, 4)], obstacles=[(3, 4)]),
    'obs_down':   make_obs(agent=[(4, 4)], obstacles=[(5, 4)]),
    'surrounded': make_obs(agent=[(4, 4)], obstacles=[(4, 5), (4, 3), (3, 4), (5, 4)]),
}

X = np.array(list(cases.values()))
logits = forward(X)
actions = np.argmax(logits, axis=1)
for name, act, log in zip(cases.keys(), actions, logits):
    print(f"{name}: action={act}, logits={np.round(log, 2)}")
